/**
 * Budget data schema (see docs/budget-data.md).
 *
 * Describes the committed files in src/data/budget/ (meta, expenditure,
 * revenue) generated by tools/ingest-budget.ts from the Statskontoret (ESV)
 * årsutfall files. Imported by src/lib/budget/ and, via tools/lib/schema.ts,
 * by the tooling. Keep it free of Astro and browser imports.
 *
 * Series are arrays aligned on the file's `years` list (index i is
 * `years[i]`). Amounts are million kronor (mn kr), nominal, one decimal.
 * `null` means the source cell was empty, which is not the same as 0.
 */
import { z } from 'zod';

export const BUDGET_STATUSES = ['final', 'preliminary'] as const;
export const budgetStatusSchema = z.enum(BUDGET_STATUSES);
export type BudgetStatus = z.infer<typeof budgetStatusSchema>;

/** One value per year in `years`, `null` where the source has no value. */
export const seriesSchema = z.array(z.number().nullable());
export type Series = z.infer<typeof seriesSchema>;

const yearsSchema = z.array(z.number().int()).min(1);
const yearKeySchema = z.string().regex(/^\d{4}$/);
const statusByYearSchema = z.record(yearKeySchema, budgetStatusSchema);

const fileInfoSchema = z.strictObject({
  /** Download URL of the zip. */
  url: z.string().url(),
  /** Release name as the file is titled by the publisher, e.g. "Årsutfall utgifter 1997 - 2025, definitivt". */
  release: z.string().min(1),
  /** Publisher status of the release, e.g. "Definitiv", "Preliminär 2". */
  status: z.string().min(1),
  /** sha256 of the CSV, used to keep `fetched` stable when nothing changed. */
  sha256: z.string().regex(/^[0-9a-f]{64}$/),
});

export const budgetMetaSchema = z.strictObject({
  source: z.string().url(),
  licence: z.literal('CC0-1.0'),
  /** Date (YYYY-MM-DD) the files were fetched. */
  fetched: z.string().regex(/^\d{4}-\d{2}-\d{2}$/),
  unit: z.literal('mn kr'),
  years: yearsSchema,
  files: z.strictObject({
    expenditure: fileInfoSchema,
    revenue: fileInfoSchema,
  }),
  /** Per-year status. Revenue status comes from ingestion config, not from the data. */
  yearStatus: z.strictObject({
    expenditure: statusByYearSchema,
    revenue: statusByYearSchema,
  }),
});
export type BudgetMeta = z.infer<typeof budgetMetaSchema>;

const anslagSchema = z.strictObject({
  /** Restated code as in the file; discontinued anslag carry a year suffix, e.g. "0501003 2024" (old ones are six characters, e.g. "020104 2008"). */
  kod: z.string().regex(/^(\d{7}( \d{4})?|[0-9A-Z]{6} \d{4})$/),
  uo: z.number().int().min(1).max(27),
  /** Display designation within the UO, e.g. "1:11". null for old six-character codes. */
  beteckning: z
    .string()
    .regex(/^\d+:\d+$/)
    .nullable(),
  namn: z.string().min(1),
  /** Last year the anslag was in the budget, from the code suffix. null if still active. */
  upphort: z.number().int().nullable(),
  /** Statens budget. */
  budget: seriesSchema,
  /** Ändringsbudgetar. */
  andrad: seriesSchema,
  utfall: seriesSchema,
});
export type Anslag = z.infer<typeof anslagSchema>;

/** Rows without a utgiftsområde: outcome per year. */
export const OVRIGT_KEYS = [
  'nettoutlaning',
  'kassamassigKorrigering',
  'alderspension',
  'utgiftstak',
  'marginal',
] as const;
export type OvrigtKey = (typeof OVRIGT_KEYS)[number];

export const expenditureSchema = z
  .object({
    years: yearsSchema,
    uo: z.array(z.strictObject({ nr: z.number().int().min(1).max(27), namn: z.string().min(1) })),
    anslag: z.array(anslagSchema),
    ovrigt: z.strictObject({
      nettoutlaning: seriesSchema,
      kassamassigKorrigering: seriesSchema,
      alderspension: seriesSchema,
      utgiftstak: seriesSchema,
      marginal: seriesSchema,
    }),
  })
  .superRefine((data, ctx) => {
    const n = data.years.length;
    const check = (series: Series, path: (string | number)[]) => {
      if (series.length !== n) {
        ctx.addIssue({
          code: 'custom',
          path,
          message: `series length ${series.length} != ${n} years`,
        });
      }
    };
    data.anslag.forEach((a, i) => {
      check(a.budget, ['anslag', i, 'budget']);
      check(a.andrad, ['anslag', i, 'andrad']);
      check(a.utfall, ['anslag', i, 'utfall']);
    });
    for (const key of OVRIGT_KEYS) check(data.ovrigt[key], ['ovrigt', key]);
    const uoNrs = new Set(data.uo.map((u) => u.nr));
    data.anslag.forEach((a, i) => {
      if (!uoNrs.has(a.uo)) {
        ctx.addIssue({ code: 'custom', path: ['anslag', i, 'uo'], message: `unknown uo ${a.uo}` });
      }
    });
    const seen = new Set<string>();
    data.anslag.forEach((a, i) => {
      if (seen.has(a.kod)) {
        ctx.addIssue({ code: 'custom', path: ['anslag', i, 'kod'], message: `duplicate ${a.kod}` });
      }
      seen.add(a.kod);
    });
  });
export type Expenditure = z.infer<typeof expenditureSchema>;

const codeSchema = z.string().regex(/^\d{4}(-\d{4})?$/);

export const revenueSchema = z
  .object({
    years: yearsSchema,
    typ: z.array(z.strictObject({ kod: codeSchema, namn: z.string().min(1) })),
    huvudgrupp: z.array(
      z.strictObject({ kod: codeSchema, typ: codeSchema, namn: z.string().min(1) }),
    ),
    titelgrupp: z.array(
      z.strictObject({ kod: codeSchema, huvudgrupp: codeSchema, namn: z.string().min(1) }),
    ),
    titlar: z.array(
      z.strictObject({
        kod: codeSchema,
        huvudgrupp: codeSchema,
        /** null for titles that hang directly under their huvudgrupp. */
        titelgrupp: codeSchema.nullable(),
        namn: z.string().min(1),
        budget: seriesSchema,
        utfall: seriesSchema,
      }),
    ),
  })
  .superRefine((data, ctx) => {
    const n = data.years.length;
    data.titlar.forEach((t, i) => {
      for (const key of ['budget', 'utfall'] as const) {
        if (t[key].length !== n) {
          ctx.addIssue({
            code: 'custom',
            path: ['titlar', i, key],
            message: `series length ${t[key].length} != ${n} years`,
          });
        }
      }
    });
    const typ = new Set(data.typ.map((x) => x.kod));
    const hg = new Set(data.huvudgrupp.map((x) => x.kod));
    const tg = new Set(data.titelgrupp.map((x) => x.kod));
    data.huvudgrupp.forEach((x, i) => {
      if (!typ.has(x.typ)) {
        ctx.addIssue({
          code: 'custom',
          path: ['huvudgrupp', i, 'typ'],
          message: `unknown typ ${x.typ}`,
        });
      }
    });
    data.titelgrupp.forEach((x, i) => {
      if (!hg.has(x.huvudgrupp)) {
        ctx.addIssue({
          code: 'custom',
          path: ['titelgrupp', i, 'huvudgrupp'],
          message: `unknown huvudgrupp ${x.huvudgrupp}`,
        });
      }
    });
    data.titlar.forEach((x, i) => {
      if (!hg.has(x.huvudgrupp)) {
        ctx.addIssue({
          code: 'custom',
          path: ['titlar', i, 'huvudgrupp'],
          message: `unknown huvudgrupp ${x.huvudgrupp}`,
        });
      }
      if (x.titelgrupp !== null && !tg.has(x.titelgrupp)) {
        ctx.addIssue({
          code: 'custom',
          path: ['titlar', i, 'titelgrupp'],
          message: `unknown titelgrupp ${x.titelgrupp}`,
        });
      }
    });
  });
export type Revenue = z.infer<typeof revenueSchema>;
